#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-09
// ============================================================================
// A context: fork skill declares no frontmatter hooks (#4683)
// ============================================================================
// WHAT THIS GUARDS
//
//   Claude Code 2.1.294 does not run a skill's frontmatter hooks when the skill
//   runs as `context: fork` (runs 913b0ab4 and c6fae215, see
//   test-review-pr-runs-inline.mjs). A fork skill with a `hooks:` block ships
//   hooks that never run. A fork skill that needs a loader runs it as a body
//   step instead.
//
//   An inline skill's hooks stay registered for the rest of the session, so an
//   inline skill may only declare `once: true` hooks, except the skills in
//   SESSION_GUARDS and review-pr post gate, whose hooks must keep firing.
//
//   Fails if: any src/skills/*/SKILL.md sets `context: fork` and has a `hooks:`
//   block; or an inline skill outside SESSION_GUARDS declares a hook command
//   without `once: true`; or the scan finds no skill with hooks (broken scan).
// ============================================================================

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const SKILLS = path.join(ROOT, 'src', 'skills');
// Inline skills whose non-once hook is the feature: a guard or a check that
// must fire on every matching call while the skill is in use.
const SESSION_GUARDS = new Set(['careful', 'code-review-playbook', 'freeze']);

const frontmatter = (text) => {
  const m = /^-{3}\n([\s\S]*?)\n-{3}\n/.exec(text);
  return m ? m[1] : '';
};

// The lines of the top-level `hooks:` block, up to the next top-level key.
const hooksBlock = (fm) => {
  const lines = fm.split('\n');
  const start = lines.findIndex((l) => /^hooks:\s*$/.test(l));
  if (start === -1) return null;
  const out = [];
  for (const l of lines.slice(start + 1)) {
    if (/^\S/.test(l)) break;
    out.push(l);
  }
  return out;
};

// One entry per `type: command` hook: whether it carries once: true. Handles
// both the block form (type/command/once on their own lines) and the flow
// form ({ type: command, command: ..., once: true }).
const commandHooks = (block) => {
  const hooks = [];
  for (let i = 0; i < block.length; i++) {
    const l = block[i];
    if (/\{\s*type:\s*command\b/.test(l)) {
      hooks.push({ command: l.trim(), once: /once:\s*true/.test(l) });
      continue;
    }
    if (!/^\s*-\s*type:\s*command\s*$/.test(l)) continue;
    const indent = l.indexOf('-');
    let once = false;
    let command = '';
    for (let j = i + 1; j < block.length; j++) {
      const next = block[j];
      const nIndent = next.search(/\S/);
      if (nIndent <= indent) break;
      if (/^\s*once:\s*true\s*$/.test(next)) once = true;
      const c = /^\s*command:\s*(.*)$/.exec(next);
      if (c) command = c[1];
    }
    hooks.push({ command, once });
  }
  return hooks;
};

const failures = [];
let withHooks = 0;
for (const name of readdirSync(SKILLS).sort()) {
  const file = path.join(SKILLS, name, 'SKILL.md');
  if (!existsSync(file)) continue;
  const fm = frontmatter(readFileSync(file, 'utf8'));
  const block = hooksBlock(fm);
  if (block === null) continue;
  withHooks++;
  if (/^context:\s*fork\s*$/m.test(fm)) {
    failures.push(`src/skills/${name}/SKILL.md: context: fork with a hooks: block; a fork never runs them (#4683)`);
    continue;
  }
  if (SESSION_GUARDS.has(name)) continue;
  for (const h of commandHooks(block)) {
    // The post gate must run on every write; this exception grants no loader.
    if (name === 'review-pr' && h.command === '"${CLAUDE_PLUGIN_ROOT}/hooks/bin/run-hook.mjs skill/review-post-gate"') continue;
    if (!h.once) {
      failures.push(`src/skills/${name}/SKILL.md: inline hook without once: true stays live for the session: ${h.command}`);
    }
  }
}

// Fork skills that lost their frontmatter loaders in #4683: each body must
// still do every loader's work, as a `run-hook.mjs" skill/<loader>` line.
// visualize-plan runs scripts/detect-plan-context.sh instead, which covers
// everything skill/plan-context-loader reported.
const run = (loader) => `run-hook.mjs" ${loader}`;
const BODY_LOADERS = {
  brainstorm: [run('skill/prior-decisions-loader'), run('skill/brainstorm-instructions-loader')],
  explore: [run('skill/repo-structure-indexer')],
  implement: [run('skill/project-convention-loader'), run('skill/implement-standards-loader'), run('skill/pattern-consistency-enforcer')],
  setup: [run('skill/setup-env-detector')],
  'visualize-plan': ['scripts/detect-plan-context.sh'],
};
for (const [name, markers] of Object.entries(BODY_LOADERS)) {
  const text = readFileSync(path.join(SKILLS, name, 'SKILL.md'), 'utf8');
  const body = text.replace(/^-{3}\n[\s\S]*?\n-{3}\n/, '');
  for (const marker of markers) {
    if (!body.includes(marker)) {
      failures.push(`src/skills/${name}/SKILL.md: body lacks \`${marker}\`, so the old hook's context is lost (#4683)`);
    }
  }
  // With no event name the output guard treats the step as an unknown event and
  // strips additionalContext, so the loader runs and prints nothing.
  for (const line of body.split('\n')) {
    if (/^(!`)?echo .*run-hook\.mjs" skill\//.test(line) && !line.includes('"hook_event_name"')) {
      failures.push(`src/skills/${name}/SKILL.md: body loader sends no hook_event_name, so its context is stripped: ${line}`);
    }
  }
}

// A body step is only an instruction: in the 2026-11-08 live run the model
// skipped both loaders in brainstorm and both in implement (#4683). Each
// context loader therefore runs as load-time shell injection, a line that
// starts with !` : Claude Code runs it while it renders the skill and puts its
// output in the text, before the model reads a word, so no step can be
// skipped. pattern-consistency-enforcer is a check after writes, not a loader,
// so it stays a step. visualize-plan's STEP 0 script was a step too, and the
// model skipped it in 1 of 2 live runs (2026-11-10), so it joins the map.
// Each entry is the exact command text, path included: ${CLAUDE_SKILL_DIR} is
// the form the live runs proved resolves at render time.
const hookLine = (loader) => `node "\${CLAUDE_SKILL_DIR}/../../hooks/bin/run-hook.mjs" ${loader}`;
const INJECTED = {
  brainstorm: [hookLine('skill/prior-decisions-loader'), hookLine('skill/brainstorm-instructions-loader')],
  explore: [hookLine('skill/repo-structure-indexer')],
  implement: [hookLine('skill/project-convention-loader'), hookLine('skill/implement-standards-loader')],
  setup: [hookLine('skill/setup-env-detector')],
  'visualize-plan': ['bash "${CLAUDE_SKILL_DIR}/scripts/detect-plan-context.sh"'],
};
// A !` command that exits non-zero aborts the whole skill, not just the
// context: rev-parse exits 128 outside a repository, and run-hook.mjs exits
// 1 or 2 on a bundle or handler error. So every load-time line in these skills
// must end in a tail that cannot fail. And under disableSkillShellExecution the
// model sees only a placeholder, so each skill says what to do then.
const POLICY_PLACEHOLDER = '[shell command execution disabled by policy]';
const NEVER_FAILS = /2>\/dev\/null \|\| (true|echo [a-z]+)`$/;
for (const [name, loaders] of Object.entries(INJECTED)) {
  const text = readFileSync(path.join(SKILLS, name, 'SKILL.md'), 'utf8');
  const lines = text.replace(/^-{3}\n[\s\S]*?\n-{3}\n/, '').split('\n');
  for (const loader of loaders) {
    const injected = lines.some((l) => l.startsWith('!`') && l.endsWith('`') && l.includes(loader));
    if (!injected) {
      failures.push(`src/skills/${name}/SKILL.md: \`${loader}\` is not a !\` load-time line, so the model can skip it (#4683)`);
    }
  }
  // Every load-time command on a line, not only the first (b137 review, #5191).
  for (const line of lines) {
    for (const inline of line.matchAll(/!`[^`]+`/g)) {
      if (!NEVER_FAILS.test(inline[0])) {
        failures.push(`src/skills/${name}/SKILL.md: load-time command can fail and abort the skill (add 2>/dev/null || true): ${inline[0]}`);
      }
    }
  }
  if (!text.includes(POLICY_PLACEHOLDER)) {
    failures.push(`src/skills/${name}/SKILL.md: says nothing for ${POLICY_PLACEHOLDER}, so with shell execution disabled the context is silently missing`);
  }
}
// implement's start sha is "none" outside a repository; Phase 6 must say what then.
{
  const ref = readFileSync(path.join(SKILLS, 'implement', 'references', 'phase-6-pattern-check.md'), 'utf8');
  if (!/start sha is `none`/.test(ref)) {
    failures.push('src/skills/implement/references/phase-6-pattern-check.md: no step for a start sha of `none` (no repository)');
  }
}

// fix-issue is the exception to the loader map: skill/issue-context-loader
// takes its number from the branch name, so on a branch like fix/ork10-...
// it loads a different issue than the argument (#4693). The body must fetch
// ISSUE_NUMBER itself instead of calling that loader.
{
  const text = readFileSync(path.join(SKILLS, 'fix-issue', 'SKILL.md'), 'utf8');
  if (text.includes(run('skill/issue-context-loader'))) {
    failures.push('src/skills/fix-issue/SKILL.md: calls skill/issue-context-loader, which reads the issue number from the branch name, not the argument');
  }
  if (!/issue view[^\n]*ISSUE_NUMBER/.test(text)) {
    failures.push('src/skills/fix-issue/SKILL.md: no `issue view` of ISSUE_NUMBER; the fork has no issue context at all');
  }
  if (!/^ISSUE_NUMBER = "\$ARGUMENTS" with the flags stripped/m.test(text)) {
    failures.push('src/skills/fix-issue/SKILL.md: ISSUE_NUMBER is not bound to the flags-stripped target; binding to the branch name or the first token is the same bug through another door');
  }
  if (/^ISSUE_NUMBER[^\n]*\$ARGUMENTS\[0\]/m.test(text)) {
    failures.push('src/skills/fix-issue/SKILL.md: ISSUE_NUMBER indexes $ARGUMENTS[0], which is the first flag, not the target (#4693)');
  }
}

if (withHooks === 0) {
  console.log('FAIL: no skill declares hooks; the scan is broken');
  process.exit(1);
}
for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log(`PASS: ${withHooks} skills declare hooks, none is a fork, and every inline hook outside the session guards is once: true`);
